language "moriarty-sherlock-draft/1";
program P {
  fn fact(n: UInt): UInt { if n == 0 { 1 } else { n * fact(n - 1) } }
  entry fact(3);
}

language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry fold(branch(leaf(4), leaf(5)));
}
